// The application owns membership and message authorization; only opaque object
// keys generated by the backend ever reach this byte store.
import { randomUUID } from 'node:crypto';
import { link, mkdir, open, unlink } from 'node:fs/promises';
import { join, resolve } from 'node:path';

export const MAX_OBJECT_BYTES = 10 * 1024 * 1024;
const objectKey = /^(?:[a-f0-9]{64}|[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12})$/;

function sizeError() {
  return Object.assign(new RangeError('Object exceeds the storage byte limit'), { code: 'OBJECT_TOO_LARGE' });
}

export function createLocalStorage({ directory, maxBytes = MAX_OBJECT_BYTES } = {}) {
  if (typeof directory !== 'string' || !directory.trim() || !Number.isSafeInteger(maxBytes) || maxBytes < 1 ||
      maxBytes > MAX_OBJECT_BYTES) throw new TypeError('Invalid local object store configuration');
  const root = resolve(directory);

  function pathFor(key) {
    if (typeof key !== 'string' || !objectKey.test(key)) throw new TypeError('Invalid storage object key');
    return join(root, key);
  }

  return Object.freeze({
    async put(key, bytes) {
      const destination = pathFor(key);
      if (!(bytes instanceof Uint8Array)) throw new TypeError('Object bytes must be a Uint8Array');
      if (bytes.byteLength > maxBytes) throw sizeError();
      const snapshot = Buffer.from(bytes);
      await mkdir(root, { recursive: true, mode: 0o700 });
      const temporary = join(root, '.partial-' + randomUUID());
      // Exclusive staging plus an atomic, no-replace link leaves the old
      // value intact on duplicate writes and never exposes a partial object.
      const output = await open(temporary, 'wx', 0o600);
      try {
        try {
          await output.writeFile(snapshot);
          await output.sync();
        } finally {
          await output.close();
        }
        await link(temporary, destination);
      } finally {
        // A cleanup error after the link cannot change whether the object
        // committed. A leftover staging file must never be addressable.
        await unlink(temporary).catch(() => {});
      }
      return { size: snapshot.byteLength };
    },
    async get(key) {
      const path = pathFor(key);
      let handle;
      try {
        handle = await open(path, 'r');
      } catch (error) {
        if (error.code === 'ENOENT') return null;
        throw error;
      }
      try {
        const stat = await handle.stat();
        if (!stat.isFile()) throw new Error('Object backing entry must be a regular file');
        if (stat.size > maxBytes) throw sizeError();
        const result = Buffer.alloc(stat.size);
        for (let offset = 0; offset < result.length;) {
          const { bytesRead } = await handle.read(result, offset, result.length - offset, offset);
          if (!bytesRead) throw new Error('Stored object changed during read');
          offset += bytesRead;
        }
        return result;
      } finally {
        await handle.close();
      }
    },
    async delete(key) {
      const path = pathFor(key);
      try {
        await unlink(path);
        return true;
      } catch (error) {
        if (error.code === 'ENOENT') return false;
        throw error;
      }
    },
  });
}
